# Generated by `cargo xtask formula` for each release; edit the generator, not this file.
class Cuilo < Formula
  desc "Generate projects and code from versioned, updatable packs"
  homepage "https://cuilo.dev"
  version "2.0.0-alpha.1"
  license "MIT"

  on_macos do
    on_arm do
      url "https://dl.cuilo.dev/v#{version}/cuilo-aarch64-apple-darwin"
      sha256 "ff22d64f685cf829aaf1a580225d62c29baa818d15619bc85720cefa34b947ca"
    end
    on_intel do
      url "https://dl.cuilo.dev/v#{version}/cuilo-x86_64-apple-darwin"
      sha256 "bfdeb14a7683efec64819d0f48eab4dab1ccfe94be40d09e5cb93c13147f0c2b"
    end
  end

  on_linux do
    on_arm do
      url "https://dl.cuilo.dev/v#{version}/cuilo-aarch64-unknown-linux-musl"
      sha256 "38ab894d0712bcf71e5bc9464b5b8a16acb4d43c2bd7ceca47a946a304328664"
    end
    on_intel do
      url "https://dl.cuilo.dev/v#{version}/cuilo-x86_64-unknown-linux-musl"
      sha256 "26cf80398775806e53fb61a3f04e02f66daaca872a6fcc65ae16b74789c9aa25"
    end
  end

  def install
    # Homebrew names the download after the version folder in its URL, so install the one file it staged; a
    # downloaded file is not executable.
    binary = Dir["*"].first
    chmod 0755, binary
    bin.install binary => "cuilo"
    generate_completions_from_executable(bin/"cuilo", "completions")
    (man1/"cuilo.1").write Utils.safe_popen_read(bin/"cuilo", "man")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/cuilo --version")
  end
end
